diff --git a/src/log.ts b/src/log.ts
index 4892c8b..ead0e72 100644
--- a/src/log.ts
+++ b/src/log.ts
@@ -1,3 +1,30 @@
+let queue: string[] = [];
+let isScheduled = false;
+
+const flush = (): void => {
+  if (queue.length === 0) {
+    isScheduled = false;
+    return;
+  }
+
+  const batch = queue.splice(0, queue.length);
+
+  batch.forEach((line) => {
+    process.stdout.write(line + "\n");
+  });
+
+  if (queue.length > 0) {
+    setImmediate(flush);
+  } else {
+    isScheduled = false;
+  }
+};
+
 export const log = (message: string): void => {
-  process.stdout.write(`${JSON.stringify({ message })}\n`);
+  queue.push(JSON.stringify({ message }));
+
+  if (!isScheduled) {
+    isScheduled = true;
+    setImmediate(flush);
+  }
 };
